);

CREATE FUNCTION pgcontext._reject_build_job_progress_regression()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.processed_units < OLD.processed_units THEN
        RAISE EXCEPTION 'build job progress cannot go backwards: % < %',
            NEW.processed_units,
            OLD.processed_units
            USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER pgcontext_build_jobs_no_progress_regression
BEFORE UPDATE OF processed_units ON pgcontext._build_jobs
FOR EACH ROW
EXECUTE FUNCTION pgcontext._reject_build_job_progress_regression();

CREATE FUNCTION pgcontext._enforce_build_job_terminal_state()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.status IN ('running', 'cancel_requested', 'validating', 'publishing') THEN
        IF NEW.backend_pid IS NULL THEN
            RAISE EXCEPTION 'active build job % must record backend_pid',
                NEW.status
                USING ERRCODE = '22023';
        END IF;
        IF NEW.backend_identity IS NULL THEN
            RAISE EXCEPTION 'active build job % must record backend_identity',
                NEW.status
                USING ERRCODE = '22023';
        END IF;
        IF NEW.completed_at IS NOT NULL THEN
            RAISE EXCEPTION 'active build job % cannot retain completed_at',
                NEW.status
                USING ERRCODE = '22023';
        END IF;
        IF NEW.lease_expires_at IS NULL THEN
            RAISE EXCEPTION 'active build job % must record lease_expires_at',
                NEW.status
                USING ERRCODE = '22023';
        END IF;
    END IF;
    IF NEW.status IN ('completed', 'failed', 'cancelled', 'abandoned') THEN
        IF NEW.backend_pid IS NOT NULL OR NEW.backend_identity IS NOT NULL THEN
            RAISE EXCEPTION 'terminal build job % cannot retain backend ownership',
                NEW.status
                USING ERRCODE = '22023';
        END IF;
        IF NEW.completed_at IS NULL THEN
            RAISE EXCEPTION 'terminal build job % must record completed_at',
                NEW.status
                USING ERRCODE = '22023';
        END IF;
        IF NEW.lease_expires_at IS NOT NULL THEN
            RAISE EXCEPTION 'terminal build job % cannot retain a lease',
                NEW.status
                USING ERRCODE = '22023';
        END IF;
    END IF;
    IF NEW.status IN ('validating', 'publishing', 'completed') AND NEW.processed_units <> NEW.total_units THEN
        RAISE EXCEPTION 'completed build job progress must equal total: % <> %',
            NEW.processed_units,
            NEW.total_units
            USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER pgcontext_build_jobs_terminal_state
BEFORE INSERT OR UPDATE OF status, backend_pid, backend_identity, lease_expires_at, completed_at, processed_units, total_units
ON pgcontext._build_jobs
FOR EACH ROW
EXECUTE FUNCTION pgcontext._enforce_build_job_terminal_state();

CREATE UNIQUE INDEX pgcontext_build_jobs_one_active_target
    ON pgcontext._build_jobs (collection_id, artifact_kind, artifact_name, target_name)
 WHERE status IN ('planned', 'running', 'cancel_requested', 'validating', 'publishing');

CREATE TABLE pgcontext._build_deltas (
    delta_sequence bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    build_job_id bigint NOT NULL REFERENCES pgcontext._build_jobs(build_job_id) ON DELETE CASCADE,
    point_id bigint NOT NULL REFERENCES pgcontext._collection_points(point_id) ON DELETE CASCADE,
    operation text NOT NULL CHECK (operation IN ('upsert', 'delete')),
    source_version bigint NOT NULL CHECK (source_version > 0),
    created_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
    UNIQUE (build_job_id, source_version, point_id)
);

CREATE FUNCTION pgcontext._capture_build_point_delta()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    delta_operation text;
    next_source_version bigint;
BEGIN
    INSERT INTO pgcontext._collection_source_revisions (
        collection_id, source_version, updated_at
    )
    VALUES (NEW.collection_id, 1, pg_catalog.now())
    ON CONFLICT (collection_id) DO UPDATE
       SET source_version = pgcontext._collection_source_revisions.source_version + 1,
           updated_at = pg_catalog.now()
    RETURNING source_version INTO STRICT next_source_version;
    delta_operation := CASE WHEN NEW.deleted_at IS NULL THEN 'upsert' ELSE 'delete' END;
    INSERT INTO pgcontext._build_deltas (
        build_job_id, point_id, operation, source_version
    )
    SELECT jobs.build_job_id, NEW.point_id, delta_operation, next_source_version
      FROM pgcontext._build_jobs AS jobs
     WHERE jobs.collection_id = NEW.collection_id
       AND (
           jobs.status IN ('running', 'cancel_requested', 'validating', 'publishing')
           OR (jobs.supervised AND jobs.status = 'planned')
       )
    ON CONFLICT (build_job_id, source_version, point_id) DO UPDATE
       SET operation = EXCLUDED.operation;
    RETURN NEW;
END;
$$;

CREATE TRIGGER pgcontext_capture_build_point_delta
AFTER INSERT OR UPDATE OF deleted_at ON pgcontext._collection_points
FOR EACH ROW
EXECUTE FUNCTION pgcontext._capture_build_point_delta();

CREATE TABLE pgcontext._generation_build_rows (
    build_job_id bigint NOT NULL REFERENCES pgcontext._build_jobs(build_job_id) ON DELETE CASCADE,
    point_id bigint NOT NULL,
    source_key text NOT NULL,
    PRIMARY KEY (build_job_id, point_id)
);

CREATE TABLE pgcontext._artifact_segments (
    artifact_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    collection_id bigint NOT NULL REFERENCES pgcontext._collections(collection_id) ON DELETE CASCADE,
    build_job_id bigint NOT NULL REFERENCES pgcontext._build_jobs(build_job_id) ON DELETE RESTRICT,
    artifact_kind text NOT NULL CHECK (artifact_kind IN ('segment', 'mmap')),
    artifact_name text NOT NULL CHECK (artifact_name <> ''),
    target_name text NOT NULL CHECK (target_name <> ''),
    generation bigint NOT NULL CHECK (generation > 0),
    segment_kind text NOT NULL CHECK (segment_kind IN ('hnsw_graph')),
    format_version int4 NOT NULL CHECK (format_version = 2),
    payload_bytes bigint NOT NULL CHECK (payload_bytes >= 0),
    checksum bigint NOT NULL,
    config_revision bigint,
    relative_path text,
    lifecycle_state text NOT NULL DEFAULT 'validated' CHECK (lifecycle_state IN ('validated', 'file_materialized', 'rebuild_required', 'retired')),
    created_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
    updated_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
    CHECK (lifecycle_state <> 'file_materialized' OR relative_path IS NOT NULL),
    UNIQUE (collection_id, artifact_kind, artifact_name, target_name, generation)
);

CREATE FUNCTION pgcontext.current_vector_config_revision(collection bigint)
RETURNS bigint
LANGUAGE sql
STABLE
AS $$
    SELECT config_revision
      FROM pgcontext._collections
     WHERE collection_id = $1
$$;

CREATE TABLE pgcontext._artifact_reader_pins (
    artifact_id bigint NOT NULL REFERENCES pgcontext._artifact_segments(artifact_id) ON DELETE CASCADE,
    backend_pid int4 NOT NULL,
    backend_identity text NOT NULL,
    pin_count int4 NOT NULL CHECK (pin_count > 0),
    updated_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
    PRIMARY KEY (artifact_id, backend_pid, backend_identity)
);

CREATE TABLE pgcontext._generation_manifests (
    generation bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    collection_id bigint NOT NULL REFERENCES pgcontext._collections(collection_id) ON DELETE CASCADE,
    build_job_id bigint NOT NULL UNIQUE REFERENCES pgcontext._build_jobs(build_job_id) ON DELETE RESTRICT,
    publication_alias text NOT NULL CHECK (publication_alias <> ''),
    source_version bigint NOT NULL CHECK (source_version > 0),
    config_revision bigint NOT NULL CHECK (config_revision > 0),
    lifecycle_state text NOT NULL DEFAULT 'staged' CHECK (
        lifecycle_state IN ('staged', 'validated', 'published', 'retiring', 'retired', 'rebuild_required')
    ),
    validation_passed boolean,
    validation_findings int4 CHECK (validation_findings IS NULL OR validation_findings >= 0),
    total_payload_bytes bigint NOT NULL DEFAULT 0 CHECK (total_payload_bytes >= 0),
    created_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
    updated_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
    CHECK ((validation_passed IS NULL) = (validation_findings IS NULL)),
    CHECK (lifecycle_state NOT IN ('validated', 'published', 'retiring', 'retired') OR validation_passed)
);

CREATE TABLE pgcontext._generation_artifacts (
    generation bigint NOT NULL REFERENCES pgcontext._generation_manifests(generation) ON DELETE CASCADE,
    artifact_kind text NOT NULL CHECK (artifact_kind IN (
        'hnsw_segment', 'hnsw_delta', 'hnsw_directory', 'ivf_centroids',
        'ivf_postings', 'quantized_codes', 'chunk_projection',
        'vector_projection', 'graph_projection', 'community_summary',
        'certification_evidence'
    )),
    artifact_name text NOT NULL CHECK (artifact_name <> ''),
    payload_bytes bigint NOT NULL CHECK (payload_bytes >= 0),
    checksum_algorithm text NOT NULL DEFAULT 'pg_hashtextextended_hex_v1' CHECK (
        checksum_algorithm = 'pg_hashtextextended_hex_v1'
    ),
    checksum bigint NOT NULL,
    payload bytea NOT NULL,
    created_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
    PRIMARY KEY (generation, artifact_kind, artifact_name),
    CONSTRAINT generation_artifact_payload_length_check CHECK (
        payload_bytes = pg_catalog.octet_length(payload)
    ),
    CONSTRAINT generation_artifact_payload_checksum_check CHECK (
        checksum_algorithm = 'pg_hashtextextended_hex_v1'
        AND checksum = pg_catalog.hashtextextended(pg_catalog.encode(payload, 'hex'), 0)
    )
);

CREATE TABLE pgcontext._generation_aliases (
    collection_id bigint NOT NULL REFERENCES pgcontext._collections(collection_id) ON DELETE CASCADE,
    publication_alias text NOT NULL CHECK (publication_alias <> ''),
    generation bigint NOT NULL UNIQUE REFERENCES pgcontext._generation_manifests(generation) ON DELETE RESTRICT,
    updated_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
    PRIMARY KEY (collection_id, publication_alias)
);

CREATE TABLE pgcontext._generation_reader_pins (
    generation bigint NOT NULL REFERENCES pgcontext._generation_manifests(generation) ON DELETE CASCADE,
    backend_pid int4 NOT NULL,
    backend_identity text NOT NULL,
    pin_count int4 NOT NULL CHECK (pin_count > 0),
    updated_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
    PRIMARY KEY (generation, backend_pid, backend_identity)
);

CREATE FUNCTION pgcontext._publish_generation(target_generation bigint)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    target_collection bigint;
    target_alias text;
    previous_generation bigint;
BEGIN
    SELECT collection_id, publication_alias
      INTO target_collection, target_alias
      FROM pgcontext._generation_manifests
     WHERE generation = target_generation
       AND lifecycle_state IN ('validated', 'published')
       AND validation_passed
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'generation % is not validated for publication', target_generation
            USING ERRCODE = '55000';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pgcontext._generation_artifacts WHERE generation = target_generation
    ) THEN
        RAISE EXCEPTION 'generation % has no artifact inventory', target_generation
            USING ERRCODE = '55000';
    END IF;

    -- A collection row always exists for a valid manifest and provides a
    -- transaction-scoped serialization point even when an alias has never
    -- been published before.
    PERFORM 1
      FROM pgcontext._collections
     WHERE collection_id = target_collection
     FOR UPDATE;

    SELECT generation
      INTO previous_generation
      FROM pgcontext._generation_aliases
     WHERE collection_id = target_collection
       AND publication_alias = target_alias
     FOR UPDATE;

    IF previous_generation IS NOT NULL AND previous_generation <> target_generation THEN
        DELETE FROM pgcontext._generation_reader_pins AS pins
         WHERE pins.generation = previous_generation
           AND NOT EXISTS (
               SELECT 1
                 FROM pg_catalog.pg_stat_activity AS activity
                WHERE activity.pid = pins.backend_pid
                  AND pg_catalog.to_char(
                          activity.backend_start AT TIME ZONE 'UTC',
                          'YYYY-MM-DD"T"HH24:MI:SS.US'
                      ) = pins.backend_identity
           );
        UPDATE pgcontext._generation_manifests
           SET lifecycle_state = CASE
                   WHEN EXISTS (
                       SELECT 1
                         FROM pgcontext._generation_reader_pins AS pins
                        WHERE pins.generation = previous_generation
                   ) THEN 'retiring'
                   ELSE 'retired'
               END,
               updated_at = pg_catalog.now()
         WHERE generation = previous_generation
           AND lifecycle_state = 'published';
    END IF;

    INSERT INTO pgcontext._generation_aliases (collection_id, publication_alias, generation)
    VALUES (target_collection, target_alias, target_generation)
    ON CONFLICT (collection_id, publication_alias) DO UPDATE
       SET generation = EXCLUDED.generation,
           updated_at = pg_catalog.now();

    UPDATE pgcontext._generation_manifests
       SET lifecycle_state = 'published', updated_at = pg_catalog.now()
     WHERE generation = target_generation;
END;
$$;

CREATE FUNCTION pgcontext._pin_generation(
    target_collection bigint,
    target_alias text
)
RETURNS bigint
LANGUAGE plpgsql
AS $$
DECLARE
    target_generation bigint;
    backend_identity_value text;
BEGIN
    SELECT aliases.generation
      INTO target_generation
      FROM pgcontext._generation_aliases AS aliases
      JOIN pgcontext._generation_manifests AS manifests USING (generation)
     WHERE aliases.collection_id = target_collection
       AND aliases.publication_alias = target_alias
       AND manifests.lifecycle_state = 'published'
     FOR SHARE OF aliases, manifests;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    SELECT pg_catalog.to_char(
               activity.backend_start AT TIME ZONE 'UTC',
               'YYYY-MM-DD"T"HH24:MI:SS.US'
           )
      INTO STRICT backend_identity_value
      FROM pg_catalog.pg_stat_activity AS activity
     WHERE activity.pid = pg_catalog.pg_backend_pid();
    INSERT INTO pgcontext._generation_reader_pins (
        generation, backend_pid, backend_identity, pin_count
    )
    VALUES (
        target_generation, pg_catalog.pg_backend_pid(), backend_identity_value, 1
    )
    ON CONFLICT (generation, backend_pid, backend_identity) DO UPDATE
       SET pin_count = pgcontext._generation_reader_pins.pin_count + 1,
           updated_at = pg_catalog.now();
    RETURN target_generation;
END;
$$;

CREATE FUNCTION pgcontext._unpin_generation(target_generation bigint)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    backend_identity_value text;
BEGIN
    SELECT pg_catalog.to_char(
               activity.backend_start AT TIME ZONE 'UTC',
               'YYYY-MM-DD"T"HH24:MI:SS.US'
           )
      INTO STRICT backend_identity_value
      FROM pg_catalog.pg_stat_activity AS activity
     WHERE activity.pid = pg_catalog.pg_backend_pid();
    UPDATE pgcontext._generation_reader_pins
       SET pin_count = pin_count - 1,
           updated_at = pg_catalog.now()
     WHERE generation = target_generation
       AND backend_pid = pg_catalog.pg_backend_pid()
       AND backend_identity = backend_identity_value
       AND pin_count > 1;
    IF NOT FOUND THEN
        DELETE FROM pgcontext._generation_reader_pins
         WHERE generation = target_generation
           AND backend_pid = pg_catalog.pg_backend_pid()
           AND backend_identity = backend_identity_value;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'generation % is not pinned by this backend', target_generation
                USING ERRCODE = '55000';
        END IF;
    END IF;
    UPDATE pgcontext._generation_manifests AS manifests
       SET lifecycle_state = 'retired', updated_at = pg_catalog.now()
     WHERE manifests.generation = target_generation
       AND manifests.lifecycle_state = 'retiring'
       AND NOT EXISTS (
           SELECT 1
             FROM pgcontext._generation_reader_pins AS pins
            WHERE pins.generation = manifests.generation
       );
END;
$$;

-- Intentionally unfiltered pre-authorization lookup. Callers need this minimal
-- collection/alias name, owner-role, and source-binding summary to resolve a
-- collection before checking membership. It must not expose source-table
-- identity, source keys, vectors, payload metadata, or operational state.
CREATE VIEW pgcontext._collection_acl AS
SELECT collection_id,
       collection_name,
       owner_role,
       source_table_oid IS NOT NULL AS has_source_table
  FROM pgcontext._collections
UNION ALL
SELECT collections.collection_id,
       aliases.alias_name AS collection_name,
       collections.owner_role,
       collections.source_table_oid IS NOT NULL AS has_source_table
  FROM pgcontext._collection_aliases AS aliases
  JOIN pgcontext._collections AS collections USING (collection_id);

CREATE VIEW pgcontext._visible_collection_vectors
WITH (security_barrier = true) AS
SELECT vectors.*
  FROM pgcontext._collection_vectors AS vectors
  JOIN pgcontext._collections AS collections USING (collection_id)
 WHERE pg_catalog.pg_has_role(SESSION_USER, collections.owner_role, 'MEMBER');

CREATE VIEW pgcontext._visible_embedding_profiles
WITH (security_barrier = true) AS
SELECT profiles.*
  FROM pgcontext._embedding_profiles AS profiles
  JOIN pgcontext._collections AS collections USING (collection_id)
 WHERE pg_catalog.pg_has_role(SESSION_USER, collections.owner_role, 'MEMBER');

CREATE VIEW pgcontext._visible_collection_sparse_vectors
WITH (security_barrier = true) AS
SELECT vectors.*
  FROM pgcontext._collection_sparse_vectors AS vectors
  JOIN pgcontext._collections AS collections USING (collection_id)
 WHERE pg_catalog.pg_has_role(SESSION_USER, collections.owner_role, 'MEMBER');

CREATE VIEW pgcontext._visible_collection_points
WITH (security_barrier = true) AS
SELECT points.*
  FROM pgcontext._collection_points AS points
  JOIN pgcontext._collections AS collections USING (collection_id)
 WHERE pg_catalog.pg_has_role(SESSION_USER, collections.owner_role, 'MEMBER');

CREATE VIEW pgcontext._visible_query_stats
WITH (security_barrier = true) AS
SELECT stats.*
  FROM pgcontext._query_stats AS stats
  JOIN pgcontext._collections AS collections USING (collection_id)
 WHERE pg_catalog.pg_has_role(SESSION_USER, collections.owner_role, 'MEMBER');

CREATE VIEW pgcontext._visible_collection_payload_columns
WITH (security_barrier = true) AS
SELECT payload_columns.*
  FROM pgcontext._collection_payload_columns AS payload_columns
  JOIN pgcontext._collections AS collections USING (collection_id)
 WHERE pg_catalog.pg_has_role(SESSION_USER, collections.owner_role, 'MEMBER');

CREATE VIEW pgcontext._visible_build_jobs
WITH (security_barrier = true) AS
SELECT jobs.*
  FROM pgcontext._build_jobs AS jobs
  JOIN pgcontext._collections AS collections USING (collection_id)
 WHERE pg_catalog.pg_has_role(SESSION_USER, collections.owner_role, 'MEMBER');

CREATE VIEW pgcontext._visible_artifact_segments
WITH (security_barrier = true) AS
SELECT artifacts.*,
       collections.collection_name
  FROM pgcontext._artifact_segments AS artifacts
  JOIN pgcontext._collections AS collections USING (collection_id)
 WHERE pg_catalog.pg_has_role(SESSION_USER, collections.owner_role, 'MEMBER');

CREATE VIEW pgcontext._visible_collection_limits
WITH (security_barrier = true) AS
SELECT collection_id,
       strict_mode,
       max_dimensions,
       max_vectors,
       max_points,
       max_filter_nodes,
       max_search_limit,
       max_candidate_budget,
       query_timeout_ms,
       max_index_memory_bytes
  FROM pgcontext._collections
 WHERE pg_catalog.pg_has_role(SESSION_USER, owner_role, 'MEMBER');

CREATE VIEW pgcontext._visible_collections
WITH (security_barrier = true) AS
SELECT collection_id,
       collection_name,
       owner_role,
       source_table_oid,
       source_schema_name,
       source_table_name
  FROM pgcontext._collections
 WHERE pg_catalog.pg_has_role(SESSION_USER, owner_role, 'MEMBER');

GRANT SELECT ON pgcontext._collection_acl TO PUBLIC;
GRANT SELECT ON pgcontext._visible_collection_vectors TO PUBLIC;
GRANT SELECT ON pgcontext._visible_embedding_profiles TO PUBLIC;
GRANT SELECT ON pgcontext._visible_collection_sparse_vectors TO PUBLIC;
GRANT SELECT ON pgcontext._visible_collection_points TO PUBLIC;
GRANT SELECT ON pgcontext._visible_query_stats TO PUBLIC;
GRANT SELECT ON pgcontext._visible_collection_payload_columns TO PUBLIC;
GRANT SELECT ON pgcontext._visible_build_jobs TO PUBLIC;
GRANT SELECT ON pgcontext._visible_artifact_segments TO PUBLIC;
GRANT SELECT ON pgcontext._visible_collection_limits TO PUBLIC;
GRANT SELECT ON pgcontext._visible_collections TO PUBLIC;

-- Drift self-healing writes. Retrieval functions run SECURITY INVOKER so that
-- source-table SELECT/RLS is enforced against the caller, which means a
-- non-superuser collection member holds no direct privilege on the private
-- catalog tables. When a dump/restore or table rewrite changes a source
-- table's oid, the query path detects the drift and refreshes the stored
-- metadata through these SECURITY DEFINER helpers so the write succeeds as the
-- extension owner.
--
-- Security: these helpers accept only identifying keys, never a caller-supplied
-- oid or attnum. Each re-derives the authoritative oid/attnum from pg_catalog
-- using the schema, table, and column names already stored in the private
-- catalog, so a call can only ever set the true current binding of the
-- already-registered source table. This is deliberate: accepting an oid would
-- let a collection member repoint _collections.source_table_oid at an unrelated
-- table they control, and the SECURITY DEFINER payload/backfill paths check
-- privileges by that oid while mutating the real table by name -- a
-- confused-deputy escalation. Each helper also re-checks owner-role membership
-- on SESSION_USER (defence in depth for direct calls) and pins search_path.
CREATE FUNCTION pgcontext._refresh_collection_source_table(
    p_collection_id bigint
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pgcontext
AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM pgcontext._collections
         WHERE collection_id = p_collection_id
           AND pg_catalog.pg_has_role(SESSION_USER, owner_role, 'MEMBER')
    ) THEN
        RAISE EXCEPTION 'permission denied to refresh collection %', p_collection_id
            USING ERRCODE = '42501';
    END IF;

    UPDATE pgcontext._collections AS collections
       SET source_table_oid = source_class.oid,
           updated_at = pg_catalog.now()
      FROM pg_catalog.pg_class AS source_class
      JOIN pg_catalog.pg_namespace AS source_namespace
        ON source_namespace.oid = source_class.relnamespace
     WHERE collections.collection_id = p_collection_id
       AND source_namespace.nspname = collections.source_schema_name
       AND source_class.relname = collections.source_table_name
       AND source_class.relkind IN ('r', 'p');
END;
$$;

CREATE FUNCTION pgcontext._refresh_vector_source_binding(
    p_collection_id bigint,
    p_vector_column_name text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pgcontext
AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM pgcontext._collections
         WHERE collection_id = p_collection_id
           AND pg_catalog.pg_has_role(SESSION_USER, owner_role, 'MEMBER')
    ) THEN
        RAISE EXCEPTION 'permission denied to refresh collection %', p_collection_id
            USING ERRCODE = '42501';
    END IF;

    UPDATE pgcontext._collection_vectors AS vectors
       SET source_table_oid = source_class.oid,
           vector_attnum = source_attribute.attnum,
           updated_at = pg_catalog.now()
      FROM pg_catalog.pg_class AS source_class
      JOIN pg_catalog.pg_namespace AS source_namespace
        ON source_namespace.oid = source_class.relnamespace
      JOIN pg_catalog.pg_attribute AS source_attribute
        ON source_attribute.attrelid = source_class.oid
     WHERE vectors.collection_id = p_collection_id
       AND vectors.vector_column_name = p_vector_column_name
       AND source_namespace.nspname = vectors.source_schema_name
       AND source_class.relname = vectors.source_table_name
       AND source_class.relkind IN ('r', 'p')
       AND source_attribute.attname = vectors.vector_column_name
       AND source_attribute.attnum > 0
       AND NOT source_attribute.attisdropped;
END;
$$;

CREATE FUNCTION pgcontext._refresh_sparse_vector_source_binding(
    p_collection_id bigint,
    p_vector_name text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pgcontext
AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM pgcontext._collections
         WHERE collection_id = p_collection_id
           AND pg_catalog.pg_has_role(SESSION_USER, owner_role, 'MEMBER')
    ) THEN
        RAISE EXCEPTION 'permission denied to refresh collection %', p_collection_id
            USING ERRCODE = '42501';
    END IF;

    UPDATE pgcontext._collection_sparse_vectors AS sparse_vectors
       SET source_table_oid = source_class.oid,
           vector_attnum = source_attribute.attnum,
           updated_at = pg_catalog.now()
      FROM pg_catalog.pg_class AS source_class
      JOIN pg_catalog.pg_namespace AS source_namespace
        ON source_namespace.oid = source_class.relnamespace
      JOIN pg_catalog.pg_attribute AS source_attribute
        ON source_attribute.attrelid = source_class.oid
     WHERE sparse_vectors.collection_id = p_collection_id
       AND sparse_vectors.vector_name = p_vector_name
       AND source_namespace.nspname = sparse_vectors.source_schema_name
       AND source_class.relname = sparse_vectors.source_table_name
       AND source_class.relkind IN ('r', 'p')
       AND source_attribute.attname = sparse_vectors.vector_column_name
       AND source_attribute.attnum > 0
       AND NOT source_attribute.attisdropped;
END;
$$;

CREATE FUNCTION pgcontext._refresh_payload_source_bindings(
    p_collection_id bigint
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pgcontext
AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM pgcontext._collections
         WHERE collection_id = p_collection_id
           AND pg_catalog.pg_has_role(SESSION_USER, owner_role, 'MEMBER')
    ) THEN
        RAISE EXCEPTION 'permission denied to refresh collection %', p_collection_id
            USING ERRCODE = '42501';
    END IF;

    UPDATE pgcontext._collection_payload_columns AS payload_columns
       SET source_table_oid = source_class.oid,
           column_attnum = source_attribute.attnum,
           updated_at = pg_catalog.now()
      FROM pg_catalog.pg_class AS source_class
      JOIN pg_catalog.pg_namespace AS source_namespace
        ON source_namespace.oid = source_class.relnamespace
      JOIN pg_catalog.pg_attribute AS source_attribute
        ON source_attribute.attrelid = source_class.oid
     WHERE payload_columns.collection_id = p_collection_id
       AND source_namespace.nspname = payload_columns.source_schema_name
       AND source_class.relname = payload_columns.source_table_name
       AND source_class.relkind IN ('r', 'p')
       AND source_attribute.attname = payload_columns.column_name
       AND source_attribute.attnum > 0
       AND NOT source_attribute.attisdropped;
END;
$$;

